    message_id NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    message_code VARCHAR2(20 CHAR) NOT NULL,
    locale VARCHAR2(10 CHAR) NOT NULL DEFAULT 'ko',
    message_format_type VARCHAR2(20 CHAR) NOT NULL DEFAULT 'FIXED',
    external_message VARCHAR2(2000 CHAR) NOT NULL,
    internal_message VARCHAR2(4000 CHAR) NOT NULL,
    parameter_count NUMBER(10) NOT NULL DEFAULT 0,
    parameter_sample VARCHAR2(1000 CHAR),
    description VARCHAR2(500 CHAR),
    use_yn CHAR(1 CHAR) NOT NULL DEFAULT 'Y',
    created_by VARCHAR2(100 CHAR) NOT NULL DEFAULT 'CPF',
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by VARCHAR2(100 CHAR) NOT NULL DEFAULT 'CPF',
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT pk_cpf_message PRIMARY KEY (message_id),
    CONSTRAINT uk_cpf_message_code_locale UNIQUE (message_code, locale)
);
CREATE INDEX ix_cpf_message_code_use ON cpf_message (message_code, use_yn);
CREATE INDEX ix_cpf_message_use ON cpf_message (use_yn);
COMMENT ON TABLE cpf_message IS 'CPF 시스템 메시지';
COMMENT ON COLUMN cpf_message.message_id IS '메시지 순번';
COMMENT ON COLUMN cpf_message.message_code IS '메시지 코드';
COMMENT ON COLUMN cpf_message.locale IS '언어 코드';
COMMENT ON COLUMN cpf_message.message_format_type IS '메시지 포맷 유형';
COMMENT ON COLUMN cpf_message.external_message IS '외부 노출 메시지';
COMMENT ON COLUMN cpf_message.internal_message IS '내부 진단 메시지';
COMMENT ON COLUMN cpf_message.parameter_count IS '파라미터 개수';
COMMENT ON COLUMN cpf_message.parameter_sample IS '파라미터 예시';
COMMENT ON COLUMN cpf_message.description IS '메시지 설명';
COMMENT ON COLUMN cpf_message.use_yn IS '사용 여부';
COMMENT ON COLUMN cpf_message.created_by IS '등록자';
COMMENT ON COLUMN cpf_message.created_at IS '등록일시';
COMMENT ON COLUMN cpf_message.updated_by IS '수정자';
COMMENT ON COLUMN cpf_message.updated_at IS '수정일시';
CREATE OR REPLACE TRIGGER trg_touch_cpf_message BEFORE UPDATE ON cpf_message FOR EACH ROW BEGIN :NEW.updated_at := CURRENT_TIMESTAMP; END;
