    lease_until TIMESTAMP(3),
    row_version NUMBER(19) NOT NULL DEFAULT 0,
    CONSTRAINT pk_cpf_unknown_result PRIMARY KEY (unknown_seq),
    CONSTRAINT uk_cpf_unknown_result_id UNIQUE (unknown_id)
);
