    CONSTRAINT uk_bat_deploy_exec_scope_idem UNIQUE (idempotency_scope, idempotency_key),
    CONSTRAINT ck_bat_deploy_exec_request_hash CHECK (REGEXP_LIKE(request_hash, '^[0-9a-f]{64}$')),
